<?php
declare(strict_types=1);
namespace OCP {interface IDBConnection {public function inTransaction():bool;public function executeQuery(string $sql,array $params):object;}}
namespace OCA\Forms\Mcp\Service {class BulkStore {}class OriginContext {public static bool $matches=true;public static function assertJobInput(array $j):void{if(!self::$matches)throw new \RuntimeException('changed');}}class OriginReadAuthority {public static bool $active=true;public static function check():bool{return self::$active;}}class CircleRuntime {public static array $calls=[];public static bool $member=true;public static function assertRecipientMember(string $actor,string $circle,string $uid,string $single):void{self::$calls[]=[$actor,$circle,$uid,$single,OriginReadAuthority::$active];if(!self::$member)throw new \RuntimeException('removed');}}}
namespace {
require_once __DIR__.'/../src/Service/CoreShareIdentity.php';require_once __DIR__.'/../src/Service/BulkTransferShares.php';
use OCA\Forms\Mcp\Service\{BulkTransferShares,BulkStore,OriginContext,OriginReadAuthority,CircleRuntime};
final class CircleRecipientAuthorityReadTest extends \PHPUnit\Framework\TestCase {
 private BulkTransferShares $service;private object $db;private array $job=['id'=>'job','uid'=>'actor','phase'=>'apply'];private array $record=['files_share_id'=>'ocCircleShare:31','approved_tuple'=>['type'=>7,'recipient'=>'circle']];private array $child=['id'=>41,'share_type'=>7,'parent'=>31,'share_with'=>'single','accepted'=>1,'permissions'=>1];
 protected function setUp():void{$this->db=new class implements \OCP\IDBConnection {public bool $live=true;public int $reads=0;public array $row=['parent'=>31,'share_with'=>'single','accepted'=>1,'permissions'=>1];public function inTransaction():bool{return$this->live;}public function executeQuery(string $sql,array $params):object{$this->reads++;return new class($this->row){public function __construct(private array $row){}public function fetch():array{return$this->row;}};}};$this->service=new BulkTransferShares($this->db,new BulkStore());(new ReflectionProperty($this->service,'finalAudienceScope'))->setValue($this->service,['job',static fn()=>null]);OriginReadAuthority::$active=true;OriginContext::$matches=true;CircleRuntime::$member=true;CircleRuntime::$calls=[];}
 private function read():void{(new ReflectionMethod($this->service,'recipientAuthorityRead'))->invoke($this->service,$this->job,$this->record,$this->child,'member');}
 public function testSourceAndNativeMembershipAreReadInSameExistingAuthorityScope():void{$this->read();self::assertSame(1,$this->db->reads);self::assertSame([['actor','circle','member','single',true]],CircleRuntime::$calls);}
 public function testRemovedMembershipCannotReuseAdmission():void{$this->read();CircleRuntime::$member=false;$this->expectException(RuntimeException::class);try{$this->read();}finally{self::assertSame(2,$this->db->reads);self::assertCount(2,CircleRuntime::$calls);}}
 public function testChangedOriginalDecisionIsDeniedBeforeMembership():void{$this->db->row['accepted']=0;$this->expectException(RuntimeException::class);try{$this->read();}finally{self::assertSame([],CircleRuntime::$calls);}}
 public function testEndedAuthorityScopeIsDeniedBeforeReading():void{OriginReadAuthority::$active=false;$this->expectException(RuntimeException::class);try{$this->read();}finally{self::assertSame(0,$this->db->reads);}}
 public function testWrongParentAndPhaseAndTransactionCannotUseRead():void{foreach(['parent','phase','transaction','job']as$kind){$this->setUp();if($kind==='parent')$this->child['parent']=32;if($kind==='phase')$this->job['phase']='stage_recipients';if($kind==='transaction')$this->db->live=false;if($kind==='job')$this->job['id']='other';$denied=false;try{$this->read();}catch(RuntimeException){$denied=true;}self::assertTrue($denied);self::assertSame(0,$this->db->reads);$this->child['parent']=31;$this->job['phase']='apply';$this->job['id']='job';}}
}
}
